14	export interface EditorDisplay {
15	  name: string;
16	  type: EditorType | 'not_set';
17	  disabled: boolean;
18	}
19	
20	class EditorSettingsManager {
21	  private readonly availableEditors: EditorDisplay[];
22	
23	  constructor() {
24	    // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
25	    const editorTypes = Object.keys(
26	      EDITOR_DISPLAY_NAMES,
27	    ).sort() as EditorType[];
28	    this.availableEditors = [
29	      {
30	        name: 'None',
31	        type: 'not_set',
32	        disabled: false,
33	      },
34	      ...editorTypes.map((type) => {
35	        const hasEditor = hasValidEditorCommand(type);
36	        const isAllowedInSandbox = allowEditorTypeInSandbox(type);
37	
38	        let labelSuffix = !isAllowedInSandbox
39	          ? ' (Not available in sandbox)'
40	          : '';
41	        labelSuffix = !hasEditor ? ' (Not installed)' : labelSuffix;
42	
43	        return {
44	          name: EDITOR_DISPLAY_NAMES[type] + labelSuffix,
45	          type,
46	          disabled: !hasEditor || !isAllowedInSandbox,
47	        };
48	      }),
49	    ];
50	  }
51	
52	  getAvailableEditorDisplays(): EditorDisplay[] {
53	    return this.availableEditors;
54	  }
55	}
56	
57	export const editorSettingsManager = new EditorSettingsManager();
