49	export function detectIdeFromEnv(): IdeInfo {
50	  if (process.env['ANTIGRAVITY_CLI_ALIAS']) {
51	    return IDE_DEFINITIONS.antigravity;
52	  }
53	  if (process.env['__COG_BASHRC_SOURCED']) {
54	    return IDE_DEFINITIONS.devin;
55	  }
56	  if (process.env['REPLIT_USER']) {
57	    return IDE_DEFINITIONS.replit;
58	  }
59	  if (process.env['CURSOR_TRACE_ID']) {
60	    return IDE_DEFINITIONS.cursor;
61	  }
62	  if (process.env['CODESPACES']) {
63	    return IDE_DEFINITIONS.codespaces;
64	  }
65	  if (isCloudShell()) {
66	    return IDE_DEFINITIONS.cloudshell;
67	  }
68	  if (process.env['TERM_PRODUCT'] === 'Trae') {
69	    return IDE_DEFINITIONS.trae;
70	  }
71	  if (process.env['MONOSPACE_ENV']) {
72	    return IDE_DEFINITIONS.firebasestudio;
73	  }
74	  if (process.env['POSITRON'] === '1') {
75	    return IDE_DEFINITIONS.positron;
76	  }
77	  if (process.env['TERM_PROGRAM'] === 'sublime') {
78	    return IDE_DEFINITIONS.sublimetext;
79	  }
80	  if (process.env['ZED_SESSION_ID'] || process.env['TERM_PROGRAM'] === 'Zed') {
81	    return IDE_DEFINITIONS.zed;
82	  }
83	  if (process.env['XCODE_VERSION_ACTUAL']) {
84	    return IDE_DEFINITIONS.xcode;
85	  }
86	  if (isJetBrains()) {
87	    return IDE_DEFINITIONS.jetbrains;
88	  }
89	  return IDE_DEFINITIONS.vscode;
90	}
