92	function verifyVSCode(
93	  ide: IdeInfo,
94	  ideProcessInfo: {
95	    pid: number;
96	    command: string;
97	  },
98	): IdeInfo {
99	  if (ide.name !== IDE_DEFINITIONS.vscode.name) {
100	    return ide;
101	  }
102	  if (
103	    !ideProcessInfo.command ||
104	    ideProcessInfo.command.toLowerCase().includes('code')
105	  ) {
106	    return IDE_DEFINITIONS.vscode;
107	  }
108	  return IDE_DEFINITIONS.vscodefork;
