111	function verifyJetBrains(
112	  ide: IdeInfo,
113	  ideProcessInfo: {
114	    pid: number;
115	    command: string;
116	  },
117	): IdeInfo {
118	  if (ide.name !== IDE_DEFINITIONS.jetbrains.name || !ideProcessInfo.command) {
119	    return ide;
120	  }
121	
122	  const command = ideProcessInfo.command.toLowerCase();
123	  const jetbrainsProducts: Array<[string, IdeInfo]> = [
124	    ['idea', IDE_DEFINITIONS.intellijidea],
125	    ['webstorm', IDE_DEFINITIONS.webstorm],
126	    ['pycharm', IDE_DEFINITIONS.pycharm],
127	    ['goland', IDE_DEFINITIONS.goland],
128	    ['studio', IDE_DEFINITIONS.androidstudio],
129	    ['clion', IDE_DEFINITIONS.clion],
130	    ['rustrover', IDE_DEFINITIONS.rustrover],
131	    ['datagrip', IDE_DEFINITIONS.datagrip],
132	    ['phpstorm', IDE_DEFINITIONS.phpstorm],
133	  ];
134	
135	  for (const [product, ideInfo] of jetbrainsProducts) {
136	    if (command.includes(product)) {
137	      return ideInfo;
138	    }
139	  }
140	
141	  return ide;
142	}
