144	export function detectIde(
145	  ideProcessInfo: {
146	    pid: number;
147	    command: string;
148	  },
149	  ideInfoFromFile?: { name?: string; displayName?: string },
150	): IdeInfo | undefined {
151	  if (ideInfoFromFile?.name && ideInfoFromFile.displayName) {
152	    return {
153	      name: ideInfoFromFile.name,
154	      displayName: ideInfoFromFile.displayName,
155	    };
156	  }
157	
158	  // Only VS Code, Sublime Text, JetBrains, Zed, and XCode integrations are currently supported.
159	  if (
160	    process.env['TERM_PROGRAM'] !== 'vscode' &&
161	    process.env['TERM_PROGRAM'] !== 'sublime' &&
162	    process.env['TERM_PROGRAM'] !== 'Zed' &&
163	    !process.env['ZED_SESSION_ID'] &&
164	    !process.env['XCODE_VERSION_ACTUAL'] &&
165	    !isJetBrains()
166	  ) {
167	    return undefined;
168	  }
169	
170	  const ide = detectIdeFromEnv();
171	  return isJetBrains()
172	    ? verifyJetBrains(ide, ideProcessInfo)
173	    : verifyVSCode(ide, ideProcessInfo);
174	}
