830	export async function renderHook<Result, Props>(
831	  renderCallback: (props: Props) => Result,
832	  options?: {
833	    initialProps?: Props;
834	    wrapper?: React.ComponentType<{ children: React.ReactNode }>;
835	  },
836	): Promise<{
837	  result: { current: Result };
838	  rerender: (props?: Props) => void;
839	  unmount: () => void;
840	  waitUntilReady: () => Promise<void>;
841	  generateSvg: () => string;
842	}> {
843	  const result = { current: undefined as unknown as Result };
844	  let currentProps = options?.initialProps as Props;
845	
846	  function TestComponent({
847	    renderCallback,
848	    props,
849	  }: {
850	    renderCallback: (props: Props) => Result;
851	    props: Props;
852	  }) {
853	    result.current = renderCallback(props);
854	    return null;
855	  }
856	
857	  const Wrapper = options?.wrapper || (({ children }) => <>{children}</>);
858	
859	  let inkRerender: (tree: React.ReactElement) => void = () => {};
860	  let unmount: () => void = () => {};
861	  let waitUntilReady: () => Promise<void> = async () => {};
862	  let generateSvg: () => string = () => '';
863	
864	  const renderResult = await render(
865	    <Wrapper>
866	      <TestComponent renderCallback={renderCallback} props={currentProps} />
867	    </Wrapper>,
868	  );
869	  inkRerender = renderResult.rerender;
870	  unmount = renderResult.unmount;
871	  waitUntilReady = renderResult.waitUntilReady;
872	  generateSvg = renderResult.generateSvg;
873	
874	  function rerender(props?: Props) {
875	    if (arguments.length > 0) {
876	      currentProps = props as Props;
877	    }
878	    act(() => {
879	      inkRerender(
880	        <Wrapper>
881	          <TestComponent renderCallback={renderCallback} props={currentProps} />
882	        </Wrapper>,
883	      );
884	    });
885	  }
886	
887	  return { result, rerender, unmount, waitUntilReady, generateSvg };
888	}
